#include "file_transfer.h"
#include "protocol.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static int read_key(const char*path,char*out,size_t size){FILE*f=fopen(path,"r");size_t n;if(!f||!fgets(out,(int)size,f)){if(f)fclose(f);return-1;}fclose(f);n=strlen(out);while(n&&(out[n-1]=='\n'||out[n-1]=='\r'||out[n-1]==' '))out[--n]=0;return n?0:-1;}
static void usage(void){fputs("usage: council-send-file --host H --port P --name N --key-file K TARGET FILE\n",stderr);}
int main(int argc,char**argv){contact arbiter;const char*local_name=NULL,*key_path=NULL,*target=NULL,*path=NULL;char file_name[COUNCIL_FILE_NAME],digest[65],line[512];uint64_t size;network_socket socket;int i;memset(&arbiter,0,sizeof(arbiter));for(i=1;i<argc;i++){if(!strcmp(argv[i],"--host")&&++i<argc)snprintf(arbiter.host,sizeof(arbiter.host),"%s",argv[i]);else if(!strcmp(argv[i],"--port")&&++i<argc)arbiter.port=(uint16_t)atoi(argv[i]);else if(!strcmp(argv[i],"--name")&&++i<argc)local_name=argv[i];else if(!strcmp(argv[i],"--key-file")&&++i<argc)key_path=argv[i];else if(!target)target=argv[i];else if(!path)path=argv[i];else{usage();return 2;}}if(!arbiter.host[0]||!arbiter.port||!local_name||!key_path||!target||!path||read_key(key_path,arbiter.shared_key,sizeof(arbiter.shared_key))||file_transfer_describe(path,file_name,&size,digest)){usage();return 2;}if(network_start()||protocol_connect_identity(&arbiter,local_name,&socket)){fputs("connection or authentication failed\n",stderr);return 1;}snprintf(line,sizeof(line),"FILE %s %s %llu %s\n",target,file_name,(unsigned long long)size,digest);if(network_send(socket,line)||network_read_line(socket,line,sizeof(line))<0){network_close(socket);return 1;}if(strcmp(line,"READY")){puts(line);network_close(socket);return 1;}if(file_transfer_send_stream(socket,path)||network_read_line(socket,line,sizeof(line))<0){network_close(socket);return 1;}puts(line);network_close(socket);network_stop();return strcmp(line,"STORED")?1:0;}
